// ============================================
// 文件管理（无翻译功能）
// ============================================

const { loadFilesFromLocal, saveFilesToLocal, getDisplayName } = modules["E:\\musicplayer\\js\\utils.js"];
let bgList = [];
let bgUrlCache = {};
let currentBgIndex = 0;

// 支持的音频格式
const AUDIO_EXTS = ['.mp3', '.wav', '.ogg', '.flac', '.m4a', '.aac', '.mp4'];

// 支持的图片格式
const IMAGE_EXTS = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.avif', '.tiff'];

// 加载音乐文件夹
function loadMusicFolder(files) {
    const audioFiles = Array.from(files).filter(f => {
        const ext = f.name.toLowerCase().slice(f.name.lastIndexOf('.'));
        return AUDIO_EXTS.includes(ext);
    });
    return audioFiles;
}

// 加载图片文件夹
function loadImageFolder(files) {
    const imageFiles = Array.from(files).filter(f => {
        const ext = f.name.toLowerCase().slice(f.name.lastIndexOf('.'));
        return IMAGE_EXTS.includes(ext) && f.size > 0 && f.size < 50 * 1024 * 1024;
    });
    return imageFiles;
}

// 设置背景图列表
function setBgList(files) {
    bgList = files;
    bgUrlCache = {};
    currentBgIndex = 0;
}

// 获取背景图列表
function getBgList() {
    return bgList;
}

// 切换背景图
function changeBg(idx) {
    if (bgList.length === 0) return null;
    
    currentBgIndex = idx % bgList.length;
    const targetFile = bgList[currentBgIndex];
    
    if (!bgUrlCache[currentBgIndex]) {
        bgUrlCache[currentBgIndex] = URL.createObjectURL(targetFile);
    }
    
    return {
        url: bgUrlCache[currentBgIndex],
        index: currentBgIndex,
        name: getDisplayName(targetFile.name)
    };
}

// 获取当前背景索引
function getCurrentBgIndex() {
    return currentBgIndex;
}

// 自动加载上次的文件夹
async function autoLoadLastFolders() {
    const savedMusic = loadFilesFromLocal('savedMusicFiles');
    const savedBg = loadFilesFromLocal('savedBgFiles');
    return { savedMusic, savedBg };
}

// 清理缓存的URL
function revokeBgUrls() {
    Object.values(bgUrlCache).forEach(url => {
        URL.revokeObjectURL(url);
    });
    bgUrlCache = {};
}

// 获取支持的音乐格式列表
function getSupportedAudioFormats() {
    return AUDIO_EXTS;
}

// 获取支持的图片格式列表
function getSupportedImageFormats() {
    return IMAGE_EXTS;
}
return { loadMusicFolder, loadImageFolder, setBgList, getBgList, changeBg, getCurrentBgIndex, autoLoadLastFolders, revokeBgUrls, getSupportedAudioFormats, getSupportedImageFormats };
